import{_ as a,o as t,c as o,a6 as r}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Back up and restore local work","description":"","frontmatter":{"title":"Back up and restore local work","docId":"user.preferences.backups","translationKey":"user.preferences.backups","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","translationRevision":"b2ae789f9c15df21b415b5bc006404dffd60430f193fdaba8cd94931e750eedc","order":20},"headers":[],"relativePath":"en/user/preferences/backups.md","filePath":"en/user/preferences/backups.md","lastUpdated":1794611623000}'),s={name:"en/user/preferences/backups.md"};function i(n,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="back-up-and-restore-local-work" tabindex="-1">Back up and restore local work <a class="header-anchor" href="#back-up-and-restore-local-work" aria-label="Permalink to &quot;Back up and restore local work {#back-up-and-restore-local-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Preserve a working setup before updates, resets or moving computers. You need storage you control and time to close TikTools cleanly. There is no universal <strong>Back up everything</strong> button in the current UI; use the specific exports and a closed-app data copy.</p><h2 id="export-reusable-definitions" tabindex="-1">Export reusable definitions <a class="header-anchor" href="#export-reusable-definitions" aria-label="Permalink to &quot;Export reusable definitions {#export-reusable-definitions}&quot;">​</a></h2><ol><li>In <strong>Automations</strong>, select the intended profile and use its export action to save a <code>.tikprofile.json</code> file. Name it with the app version and date.</li><li>For a single reusable template, use the template dialog&#39;s download/export surface to save <code>.tiktemplate.json</code> where offered.</li><li>Inspect the exported file before sharing it. Templates can contain destinations and configuration values. A profile export is not a copy of balances, analytics, runtime variables, media files or account credentials.</li></ol><h2 id="copy-the-local-data" tabindex="-1">Copy the local data <a class="header-anchor" href="#copy-the-local-data" aria-label="Permalink to &quot;Copy the local data {#copy-the-local-data}&quot;">​</a></h2><ol><li>Stop LIVE activity and any collaboration serving, then exit TikTools normally. Wait until the host has stopped writing.</li><li>Locate the active data root. Defaults are <code>%LOCALAPPDATA%\\TikTools</code> on Windows and <code>~/.local/share/TikTools</code> on Linux, or <code>TikTools</code> beneath <code>XDG_DATA_HOME</code> when configured. A custom <code>TIKTOOLS_HOME</code> or per-directory override changes the location.</li><li>Copy the root and any separately overridden data, plugin, plugin-data and plugin-store directories to a dated backup folder. Copy the complete closed database directory, including any SQLite sidecar files present, rather than selecting only one <code>.db</code> file.</li><li>Preserve the referenced audio files separately: audio actions keep paths instead of importing sound bytes. Record the app version and custom directory locations with the backup.</li><li>Protect the copy because local configuration can contain private values. Cloud authentication lives in the operating system credential store and is not transported by this folder copy.</li></ol><h2 id="restore-and-verify" tabindex="-1">Restore and verify <a class="header-anchor" href="#restore-and-verify" aria-label="Permalink to &quot;Restore and verify {#restore-and-verify}&quot;">​</a></h2><p>With TikTools closed, preserve the current folder as a separate recovery copy. Restore the saved files to the intended paths and start a compatible version. Inspect profile selection, balances, variables and media paths before reconnecting. For portable definitions, import the exported profile/template through Automations; imported definitions remain disabled until explicit activation.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Expected result, status and recovery {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Closed-app copies and the named import/export surfaces are available recovery methods, without a universal cross-version restore guarantee. Cloud Changes is not a full backup. If a restored version rejects data, stop and return to the preserved copy; reinstalling an older binary does not undo a database migration. See <a href="./../updates.html">updates</a> and <a href="./troubleshooting.html">troubleshooting</a>.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Individual path overrides take precedence over <code>TIKTOOLS_HOME</code>: <code>TIKTOOLS_DATA_DIR</code> contains the databases, <code>TIKTOOLS_PLUGINS_DIR</code> installed packages, <code>TIKTOOLS_PLUGIN_DATA_DIR</code> plugin state, and <code>TIKTOOLS_PLUGIN_STORE_DIR</code> package-store state. <code>TIKTOOLS_LOG_DIR</code> and <code>TIKTOOLS_TEMP_DIR</code> select logs and temporary files. Relative values resolve against the launching working directory. Before backup, inspect <code>tiktools api call system.info --json</code> for effective paths and record inherited overrides; copy data/package/state directories with the host stopped, including existing WAL/SHM sidecars. Logs are support evidence, not a replacement for the databases.</p><p><code>system.info</code> reports effective home/dataDir; resolve the other directories from the host’s actual launch environment, not an unrelated terminal. Use <code>system.health</code> for analytics ready/pending and LIVE ingress counters.</p>',14)])])}const f=a(s,[["render",i]]);export{h as __pageData,f as default};
